from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(group: str) -> bool:
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')' and stack and stack[-1] == '(':
                stack.pop()
            else:
                return False
        return len(stack) == 0

    paren_string = paren_string.replace(" ", "")
    groups = []
    start = 0
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while count != 0:
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                j += 1
            groups.append(paren_string[i:j])
            start = j

    balanced_groups = [group for group in groups if is_balanced(group)]
    return balanced_groups

# Test the function
